export function levelOneAreaAt(x,z){return LEVEL_ONE_AREAS[Math.max(0,Math.min(LEVEL_ONE_AREAS.length-1,Math.floor((6-z)/LEVEL_ONE_AREA_SPACING)))];}
export function isLevelOneSheltered(x,z){return LEVEL_ONE_AREAS.some(a=>a.shelters.some(r=>x>=r.minX&&x<=r.maxX&&z>=r.minZ&&z<=r.maxZ));}
export const LEVEL_ONE_CRATES=LEVEL_ONE_AREAS.flatMap(a=>a.crates);
export const LEVEL_ONE_OBSTACLES=LEVEL_ONE_AREAS.flatMap(a=>[...a.walls,...a.props,...a.crates.map(c=>({...c,w:.85,d:.85}))]);
const buckets=new Map(),BUCKET=8;
for(const o of LEVEL_ONE_OBSTACLES){for(let x=Math.floor((o.x-o.w/2-.5)/BUCKET);x<=Math.floor((o.x+o.w/2+.5)/BUCKET);x++)for(let z=Math.floor((o.z-o.d/2-.5)/BUCKET);z<=Math.floor((o.z+o.d/2+.5)/BUCKET);z++){const k=x+','+z;if(!buckets.has(k))buckets.set(k,[]);buckets.get(k).push(o)}}
export function levelOneCollides(x,z,r=.22){
 if(!Number.isFinite(x)||!Number.isFinite(z)||x-r< -18||x+r>18||z+r>6||z-r< -606)return true;
 const obstacles=r<=.5?(buckets.get(Math.floor(x/BUCKET)+','+Math.floor(z/BUCKET))||[]):LEVEL_ONE_OBSTACLES;
 return obstacles.some(o=>Math.abs(x-o.x)<o.w/2+r&&Math.abs(z-o.z)<o.d/2+r);
}
export const LEVEL_ONE_KNOWN_ROUTE=LEVEL_ONE_AREAS.flatMap(a=>a.route);
